#!/usr/bin/env bash
cd "$W" || exit 1
if [ ! -f recovered.py ]; then echo "FAIL: no recovered.py"; exit 0; fi
python3 - <<'PY'
import importlib.util

spec = importlib.util.spec_from_file_location("recovered", "recovered.py")
mod = importlib.util.module_from_spec(spec)
try:
    spec.loader.exec_module(mod)
except Exception as e:
    print("FAIL: import error:", e); raise SystemExit(0)

def ground_truth(x):
    return ((x * 137) ^ 0x5A) + 13

held_out = [11, 50, 200, 777, 4096, -7, 0]
bad = []
for x in held_out:
    try:
        got = mod.transform(x)
    except Exception as e:
        bad.append((x, f"error: {e}")); continue
    exp = ground_truth(x)
    if got != exp:
        bad.append((x, f"got {got} expected {exp}"))

print("FAIL:", bad) if bad else print("PASS")
PY

#!/usr/bin/env bash
cd "$W" || exit 1
python3 - <<'PY'
import re, sys

text = open('fsmir2.sv').read()
m = re.search(r"assign solved = c == 9'(b[01]+);", text)
target = m.group(1)

block_re = re.compile(r"9'(b[01]+)\s*:\s*case\(di\)\n((?:.*\n)*?)\s*default: c <= 9'b0;\n\s*endcase")
edge_re = re.compile(r"8'b([01]+): c <= 9'(b[01]+);")

graph = {}
for bm in block_re.finditer(text):
    state = bm.group(1)
    edges = {}
    for em in edge_re.finditer(bm.group(2)):
        edges[int(em.group(1), 2)] = em.group(2)
    graph[state] = edges

try:
    candidate = open('answer.txt', 'rb').read()
except FileNotFoundError:
    print('FAIL: no answer.txt'); sys.exit(0)

state = 'b0'
for byte in candidate:
    nxt = graph.get(state, {}).get(byte)
    state = nxt if nxt is not None else 'b0'

print('PASS' if state == target else f'FAIL: ended at {state}, wanted {target}')
PY

