#!/usr/bin/env bash
set -e
cd "$W" || exit 1
python3 - <<'PY'
import re
from collections import deque

text = open('fsmir2.sv').read()
m = re.search(r"assign solved = c == 9'(b[01]+);", text)
target = m.group(1)

block_re = re.compile(r"9'(b[01]+)\s*:\s*case\(di\)\n((?:.*\n)*?)\s*default: c <= 9'b0;\n\s*endcase")
edge_re = re.compile(r"8'b([01]+): c <= 9'(b[01]+);")

graph = {}
for bm in block_re.finditer(text):
    state = bm.group(1)
    edges = {}
    for em in edge_re.finditer(bm.group(2)):
        edges[em.group(2)] = int(em.group(1), 2)
    graph[state] = edges

start = 'b0'
q = deque([(start, b'')])
seen = {start}
found = None
while q:
    cur, path = q.popleft()
    if cur == target:
        found = path
        break
    for nxt, byteval in graph.get(cur, {}).items():
        if nxt not in seen:
            seen.add(nxt)
            q.append((nxt, path + bytes([byteval])))

open('answer.txt', 'wb').write(found)
PY

#!/usr/bin/env bash
set -e
cd "$W" || exit 1
python3 - <<'PY'
import re

text = open('llvm.ll').read()

def parse_llvm_bytes(raw):
    out = bytearray()
    i = 0
    while i < len(raw):
        if raw[i] == chr(92) and i+2 < len(raw) and raw[i+1] in '0123456789ABCDEF' and raw[i+2] in '0123456789ABCDEF':
            out.append(int(raw[i+1:i+3], 16))
            i += 3
        else:
            out.append(ord(raw[i]))
            i += 1
    return bytes(out)

def get_global(name):
    m = re.search(r'@' + name + r' = dso_local global \[\d+ x i8\] c"(.*?)", align', text)
    return parse_llvm_bytes(m.group(1))

flag = get_global('flag')
a1 = get_global('a1')
a2 = get_global('a2')
a3 = get_global('a3')

def ror1(b):
    return ((b >> 1) | ((b & 1) << 7)) & 0xFF

def nibbleswap(b):
    return ((b & 0xF) << 4) | ((b >> 4) & 0xF)

n = len(flag)
buf5 = [ror1(flag[a3[i]]) for i in range(n)]
buf4 = [nibbleswap(buf5[a2[i]]) for i in range(n)]
inp = bytes(buf4[a1[i]] ^ 23 for i in range(n))

open('answer.txt', 'wb').write(inp)
PY
